import{_ as n,h as o,i as a,c as m,v as t,p,x as i,m as s,e as h,S as c}from"./chunks/framework.Dvtg8yj2.js";const b=JSON.parse('{"title":"2×2 patch merge 控制视觉 token 数","description":"","frontmatter":{"title":"2×2 patch merge 控制视觉 token 数","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen-vl-patch-merge.md","filePath":"llm/qwen-vl-patch-merge.md","lastUpdated":1788454257000}'),l={name:"llm/qwen-vl-patch-merge.md"};function d(_,e,L,V,g,E){const r=o("Mermaid");return a(),m("div",null,[e[1]||(e[1]=t('<h1 id="_2×2-patch-merge-控制视觉-token-数" tabindex="-1">2×2 patch merge 控制视觉 token 数 <a class="header-anchor" href="#_2×2-patch-merge-控制视觉-token-数" aria-label="Permalink to &quot;2×2 patch merge 控制视觉 token 数&quot;">​</a></h1><div class="epigraph"><p>原生分辨率会把视觉序列拉得很长；先把相邻四个 patch 合成一个标记，再交给语言模型，长度才压得住。</p><footer>—— Wang 等，Qwen2-VL，2024；Qwen2.5-VL / Qwen3-VL 技术报告</footer></div><p>动态分辨率让 ViT 按原图像素切块，不再把图缩到固定边长。代价立刻出现：一张高清扫描件可以生成数千个 patch，若原样送进 Decoder，prefill 的二次注意力与 KV 缓存都会被视觉侧撑爆。Qwen2-VL 起在 ViT 之后加一层简单的空间合并：相邻 \\(2\\times 2\\) 个 patch 拼成一个视觉 token。Qwen2.5-VL 与 Qwen3-VL 沿用同一压缩比，只是把投影写成两层 MLP，并与语言模型隐维对齐。本篇只写这一步合并如何控制序列长度，不把窗口注意力或 DeepStack 再展开成并列架构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>视觉编码器以固定 patch 边长 \\(p\\) 切图。Qwen2-VL / Qwen2.5-VL 取 \\(p=14\\)。高 \\(H\\)、宽 \\(W\\) 的图得到</p> \\[N_{\\mathrm{patch}}=\\frac{H}{p}\\cdot\\frac{W}{p} \\]<p>个 ViT 标记。原生分辨率意味着 \\(H,W\\) 随输入变，文档、截屏、海报都会把 \\(N_{\\mathrm{patch}}\\) 推到数千。语言模型的上下文既要装视觉序列，又要装提问与历史，视觉侧若按 patch 一对一进 Decoder，多图与长视频会先把预算吃完。</p><p>LLaVA-NeXT 一类方案用 AnyRes：把大图切成若干固定分辨率的子图，每块各自编码再拼接。它控制的是「块数 × 固定 token」，不是「随像素线性增长后再整体压缩」。Qwen 系列走另一条路：ViT 仍看细网格，送进 LLM 之前再做一次空间下采样。问题因此是：下采样必须可微、必须保持二维邻接，并且压缩比要足够把 \\(224\\times 224\\) 量级的图压到几十个标记，同时不把文字笔画糊成一团。</p><p><span class="marginnote">合并发生在 ViT 之后、语言模型之前。ViT 内部仍按未合并的 patch 做注意力，细空间结构先在编码器里混合，再被压成较短的视觉前缀。</span></p><h3 id="长度为啥不能只靠缩小输入图" tabindex="-1">长度为啥不能只靠缩小输入图 <a class="header-anchor" href="#长度为啥不能只靠缩小输入图" aria-label="Permalink to &quot;长度为啥不能只靠缩小输入图&quot;">​</a></h3><p>把图先缩到 \\(224\\times 224\\) 再编码，token 数固定，但小字、表格线、角标会先被插值抹掉。文档与 OCR 恰恰依赖这些高频细节。动态分辨率把细节留给 ViT；若不同时压缩送进 LLM 的序列，细节预算会变成上下文爆炸。\\(2\\times 2\\) 合并是这两极之间的硬约定：编码器按 \\(14\\) 像素看，语言模型按 \\(28\\) 像素当一个视觉词。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="相邻四-patch-拼成一词" tabindex="-1">相邻四 patch 拼成一词 <a class="header-anchor" href="#相邻四-patch-拼成一词" aria-label="Permalink to &quot;相邻四 patch 拼成一词&quot;">​</a></h3><p>记 ViT 末层（或 merger 输入）在网格 \\((i,j)\\) 上的隐向量为 \\(\\mathbf{h}_{i,j}\\in\\mathbb{R}^{d_v}\\)。空间合并大小 \\(s=2\\)，把</p> \\[\\mathbf{u}_{i,j}=\\big[\\mathbf{h}_{2i,2j};\\,\\mathbf{h}_{2i,2j+1};\\,\\mathbf{h}_{2i+1,2j};\\,\\mathbf{h}_{2i+1,2j+1}\\big]\\in\\mathbb{R}^{4d_v} \\]<p>送入 LayerNorm 与两层 MLP，映到语言模型隐维 \\(d\\)：</p> \\[\\mathbf{z}_{i,j}=\\mathrm{MLP}\\big(\\mathrm{LN}(\\mathbf{u}_{i,j})\\big)\\in\\mathbb{R}^{d}. \\]<p>实现里常把整段序列 <code>view</code> 成每行 \\(4d_v\\)，再走 GELU 夹心的线性层。Qwen2-VL 技术报告把这一层称作 ViT 之后的简单 MLP；开源实现里模块名是 PatchMerger，默认 <code>spatial_merge_size=2</code>。Qwen3-VL 仍写「两层 MLP 把 \\(2\\times 2\\) 视觉特征压成一个视觉 token」，压缩比没有改成 \\(3\\times 3\\) 或可学习池化。</p><p>压缩后的网格边长各除以 \\(2\\)，标记数为</p> \\[N_{\\mathrm{tok}}=\\frac{H}{2p}\\cdot\\frac{W}{2p}=\\frac{N_{\\mathrm{patch}}}{4}. \\]<p>Qwen2-VL 给出对照：分辨率 \\(224\\times 224\\)、\\(p=14\\) 时，\\(N_{\\mathrm{patch}}=16\\times 16=256\\)，合并后 \\(8\\times 8=64\\)，再在两端加上视觉起止特殊标记，进入 LLM 的是 \\(66\\) 个视觉相关 token。边长必须能被 \\(2p\\) 整除。Qwen2.5-VL 因此在送入 ViT 前把高宽调整为 \\(28\\) 的倍数——\\(28=2\\times 14\\)，正好对齐「一 token 对应 \\(28\\times 28\\) 像素」。</p>',21)),(a(),p(c,null,{default:i(()=>[h(r,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20Img%5B%22%E5%8E%9F%E7%94%9F%E5%88%86%E8%BE%A8%E7%8E%87%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20Patch%5B%22p%20%E7%AD%89%E4%BA%8E%2014%20%E5%88%87%E5%9D%97%22%5D%0A%20%20Patch%20--%3E%20ViT%5B%22ViT%20%E6%8C%89%20patch%20%E7%BC%96%E7%A0%81%22%5D%0A%20%20ViT%20--%3E%20Merge%5B%222%20%E4%B9%98%202%20%E6%8B%BC%E6%8E%A5%E5%86%8D%20MLP%22%5D%0A%20%20Merge%20--%3E%20LLM%5B%22%E8%BF%9B%E5%85%A5%E8%AF%AD%E8%A8%80%E6%A8%A1%E5%9E%8B%E7%9A%84%E8%A7%86%E8%A7%89%E5%89%8D%E7%BC%80%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h3 id="与投影器、与-anyres-的分工" tabindex="-1">与投影器、与 AnyRes 的分工 <a class="header-anchor" href="#与投影器、与-anyres-的分工" aria-label="Permalink to &quot;与投影器、与 AnyRes 的分工&quot;">​</a></h3><p>LLaVA 的投影器把<strong>已经固定长度</strong>的视觉序列从 ViT 维映到 LLM 维，不负责把 \\(N\\) 除以四。Qwen 的 merger 同时做两件事：空间下采样与维数对齐。AnyRes 用多块固定分辨率拼接来逼近大图，块与块之间没有「四合一」的共享 MLP；Qwen 用单幅动态网格加一次规则合并。两者都在控制视觉 token 数，轴不同：一块是「先切图再编码」，一块是「先细编码再合并」。不要把 \\(2\\times 2\\) merge 写成任意分辨率池化，也不要写成可学习的 token 剪枝——报告里是规则邻域拼接，不是 Top-\\(k\\) 丢弃。</p><p><span class="marginnote">视频侧 Qwen2.5-VL 还把连续两帧在时间上打成一个 3D patch，那是时间维的另一次压缩，与空间 \\(2\\times 2\\) 正交。本篇的 \\(N_{\\mathrm{tok}}\\) 公式只写空间合并。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>四合一能工作，是因为相邻 patch 在自然图像与印刷品上都高度相关：同一字形、同一表格线、同一色块会跨过 \\(14\\) 像素边界。MLP 看到的是已经过 ViT 混合的四元组，不是生像素，所以合并更接近「读完邻域再写一个词」，而不是「四个互不相关的向量硬平均」。压缩比固定为 \\(4\\)，梯度路径短，训练稳定，也让动态分辨率的长度预测成为算术：像素定了，token 数就定了。</p><p>对 OCR 而言，一个合并 token 覆盖 \\(28\\times 28\\) 像素。中文印刷体在常见扫描 dpi 下，这一窗口往往仍能包住一个字或半个词；英文小字、密集脚注则可能多个字符挤进同一 token。这是后续 <a href="/llm/qwen-ocr-text-grounding">文字定位</a> 仍要靠更高输入分辨率补救的原因：合并比不改，只把图开得更大，让每个 \\(28\\times 28\\) 窗口里的字更少。</p><p><span class="marginnote">特殊标记 <code>&amp;lt;|vision_start|&amp;gt;</code> 与 <code>&amp;lt;|vision_end|&amp;gt;</code> 包住压缩后的序列，让语言模型知道视觉前缀的边界。它们不参与 \\(2\\times 2\\) 合并，却计入上下文长度。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>\\(s=2\\) 是系列默认，不是 sweeper 搜出来的最优整数。\\(s=1\\) 等于不压缩，动态分辨率的长度不可接受；\\(s=4\\) 则一 token 覆盖 \\(56\\times 56\\) 像素，表格细线与角标更容易糊。报告没有把 merge size 写成任务相关的可学习门，复现时应把它当成与 \\(p=14\\) 绑在一起的架构常数。</p><p>合并是规则网格，不能处理「这四个 patch 语义无关、不该合成一词」的情况：跨栏缝、图文交界、被裁切的半个字，都会被强制拼进同一 \\(\\mathbf{u}_{i,j}\\)。窗口注意力可以在 ViT 内部先做局部混合，缓解但不取消这一硬切。另一边界是多图拼接：每张图各自合并，再与文本交错；merger 不在图与图之间共享邻域。</p><p>工程上，merger 的输出维必须等于 LLM 隐维（Qwen2.5-VL 的 3B/7B/72B 分别把 merger 输出接到 \\(2048\\)、\\(3584\\)、\\(8192\\)）。换底座语言模型却忘了改 merger 最后一层，是静默的形状错误。推理时 <code>min_pixels</code> / <code>max_pixels</code> 通过限制 \\(H\\times W\\) 间接限制 \\(N_{\\mathrm{tok}}\\)；它们与 \\(2\\times 2\\) 合并相乘，而不是替代合并。把像素上限开到很大却以为 token 仍接近 \\(64\\)，会把文档页的上下文直接打满。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>动态分辨率按 \\(p=14\\) 产生可变长 patch 序列；\\(2\\times 2\\) patch merge 把相邻四向量拼接，经 MLP 压成一个与 LLM 对齐的视觉 token，长度除以四。</li><li>\\(224\\times 224\\) 时合并后约 \\(64\\) 个视觉标记，加起止符后为 \\(66\\)；高宽需对齐 \\(28\\) 的倍数。</li><li>合并在 ViT 之后，细网格注意力仍在编码器内发生；它不是 AnyRes 切块，也不是可学习剪枝。</li><li>固定压缩比让长度可事先算清，也把过密文字挤进同一 token，OCR 要靠提高输入分辨率而不是改 \\(s\\)。</li><li>出处：Wang 等，<em>Qwen2-VL</em>，2024；Qwen2.5-VL 技术报告；Qwen3-VL 技术报告（仍用 \\(2\\times 2\\) MLP merger）；对照 LLaVA-NeXT 的 AnyRes 切块。</li></ul>',13))])}const f=n(l,[["render",d]]);export{b as __pageData,f as default};
